-------------------
---- HOST LAYER ----
-------------------

-- Everything tied to one physical laptop -- panel modes, monitor descriptions,
-- WORKSPACE_COUNT -- lives in hosts/<id>/hypr.lua, reached through the
-- .config/hypr/hosts symlink. See hosts/README.md.
--
-- The id comes from ~/.config/dotfiles-host when pinned, otherwise from a slug
-- of the DMI vendor and model, so a fresh clone works before anything is set up.

local function read_first_line(path)
    local f = io.open(path, "r")
    if not f then
        return nil
    end
    local line = f:read("l")
    f:close()
    if line == nil or line == "" then
        return nil
    end
    return line
end

local function slugify(value)
    return (value:lower():gsub("[^a-z0-9]+", "-"):gsub("^%-+", ""):gsub("%-+$", ""))
end

local function resolve_host_id()
    local env = os.getenv("DOTFILES_HOST")
    if env and env ~= "" then
        return env
    end

    local config_home = os.getenv("XDG_CONFIG_HOME") or ((os.getenv("HOME") or "") .. "/.config")
    local pinned = read_first_line(config_home .. "/dotfiles-host")
    if pinned then
        return pinned
    end

    local dmi = "/sys/devices/virtual/dmi/id/"
    local vendor = read_first_line(dmi .. "sys_vendor")
    local model = read_first_line(dmi .. "product_name") or read_first_line(dmi .. "board_name")
    if not model then
        return nil
    end

    -- Skip the vendor prefix when the model already names the manufacturer.
    if vendor and not model:lower():find(vendor:lower(), 1, true) then
        model = vendor .. " " .. model
    end
    return slugify(model)
end

-- Defaults, so an unconfigured machine still comes up with a usable desktop.
WORKSPACE_COUNT = 5
HOST_ID = resolve_host_id()

local host_loaded = false
if HOST_ID then
    host_loaded = pcall(require, "hosts." .. HOST_ID .. ".hypr")
end

if not host_loaded then
    -- No layer for this machine yet: let every output self-configure.
    hl.monitor({
        output   = "",
        mode     = "preferred",
        position = "auto",
        scale    = 1,
    })
end


