-- Set programs that you use
local HOME = os.getenv("HOME") or "/home/kp"

local function is_file_exists(name)
    local f = io.open(name, "r")
    if f ~= nil then
        io.close(f)
        return true
    else
        return false
    end
end

pcall(require, "hyprland.lib")
pcall(require, "hyprland.variables")
if is_file_exists(HOME .. "/.config/hypr/custom/variables.lua") then
    pcall(require, "custom.variables")
end

local function workspace_in_group(i)
    return i
end

