-------------------
---- AUTOSTART ----
-------------------

-- See https://wiki.hypr.land/Configuring/Basics/Autostart/
-- This runs on both initial config load and reload. Every command is guarded so
-- reloading Hyprland cannot create duplicate background services.
local function ensure_desktop_services()
    hl.exec_cmd("dbus-update-activation-environment --systemd WAYLAND_DISPLAY XDG_CURRENT_DESKTOP HYPRLAND_INSTANCE_SIGNATURE; systemctl --user import-environment WAYLAND_DISPLAY XDG_CURRENT_DESKTOP HYPRLAND_INSTANCE_SIGNATURE")
    hl.exec_cmd("hyprctl plugins list | grep -q 'Plugin GloView' || hyprctl plugin load /usr/lib/gloview.so")
    -- The wrapper takes an flock, so a second call is a no-op instead of a second bar.
    hl.exec_cmd(HOME .. "/.local/bin/waybar")
    hl.exec_cmd("pgrep -x swaync || swaync")
    hl.exec_cmd("pgrep -x hypridle || hypridle")
    -- Watches AC state and the battery level; its own flock makes this a no-op
    -- when one is already running.
    hl.exec_cmd(HOME .. "/.local/bin/battery-saver daemon")
    -- Start wallpaper daemon once; seed a wallpaper only on that first start
    -- so Hyprland reload does not reshuffle the current image.
    hl.exec_cmd("if ! pgrep -x awww-daemon >/dev/null; then awww-daemon; " .. HOME .. "/.config/hypr/scripts/set-wallpaper.sh; fi")
    hl.exec_cmd("pgrep -x kanshi || kanshi")
    hl.exec_cmd("systemctl --user start hyprpolkitagent.service")
    hl.exec_cmd("pgrep -f nm-applet || nm-applet --indicator")
    hl.exec_cmd("pgrep -x blueman-applet || blueman-applet")
    hl.exec_cmd("pgrep -f 'wl-paste --type text --watch cliphist store' || wl-paste --type text --watch cliphist store")
    hl.exec_cmd("pgrep -f 'wl-paste --type image --watch cliphist store' || wl-paste --type image --watch cliphist store")
    hl.exec_cmd("pgrep -x easyeffects || easyeffects --service-mode")
    hl.exec_cmd("for c in 0 1 2 3; do amixer -c $c sset 'Mic Boost' 1 2>/dev/null; done || true")
end

ensure_desktop_services()
pcall(hl.on, "hyprland.start", ensure_desktop_services)
pcall(hl.on, "config.reloaded", ensure_desktop_services)


