    match = {
        class = "^(steam|Steam)$",
        title = "^(Friends List|Steam - News|Settings|Music Player|Screenshot Manager|Steam Guard|Compact Mode)$",
    },
    float = true,
})

-- Auto-Float Utility Dialogs & System Popups
hl.window_rule({
    name  = "auto-float-utilities",
    match = {
        class = "^(pavucontrol|org.pulseaudio.pavucontrol|nm-connection-editor|blueman-manager|gnome-calculator|org.gnome.Calculator|feh|imv|mpv|file-roller|nwg-look|qt5ct|qt6ct|waypaper|wlogout)$",
    },
    float = true,
    center = true,
})

hl.window_rule({
    name  = "auto-float-dialogs",
    match = {
        title = "^(Open File|Select a File|Choose Files|Save As|Confirm to replace|File Operation Progress)$",
    },
    float = true,
    center = true,
})

-- Picture-in-Picture Floating & Pinning
hl.window_rule({
    name  = "pip-window",
    match = { title = "^(Picture-in-Picture|Picture in picture)$" },
    float = true,
    pin   = true,
    no_initial_focus = true,
    suppress_event   = "activate",
})

-- Dropdown Scratchpad Terminal Rules
hl.workspace_rule({
    workspace = "special:terminal",
    on_created_empty = "kitty --class scratchpad-term",
})

hl.window_rule({
    name  = "scratchpad-term-rule",
    match = { class = "^scratchpad-term$" },
    float = true,
    size  = { "80%", "75%" },
    center = true,
})
